create function pg_temp.op(k text,e uuid,b integer,p jsonb) returns jsonb language sql as $$ select jsonb_build_object('operation_id',gen_random_uuid(),'kind',k,'entity_id',e,'base_revision',b,'device_id','e8000000-0000-4000-8000-000000000001','payload',p,'created_at','2026-10-04T12:00:00Z') $$;
create function pg_temp.sync(o jsonb) returns jsonb language sql as $$ select public.apply_operations('68000000-0000-4000-8000-000000000001',jsonb_build_array(o))->'results'->0 $$;
create function pg_temp.review(d uuid) returns jsonb language sql as $$ select public.get_workout_correction(auth.uid(),'68000000-0000-4000-8000-000000000001','b8000000-0000-4000-8000-000000000001',d) $$;
create function pg_temp.confirm(d uuid,r uuid default gen_random_uuid()) returns jsonb language plpgsql as $$ declare v jsonb; begin v:=pg_temp.review(d); return public.apply_workout_correction(auth.uid(),'68000000-0000-4000-8000-000000000001','b8000000-0000-4000-8000-000000000001',d,r,(v->>'workout_revision')::integer,(v->>'entity_revision')::integer,(v->>'exercise_revision')::integer); end $$;
create function pg_temp.error(q text) returns text language plpgsql as $$ begin execute q; return 'NO_ERROR'; exception when others then return sqlerrm; end $$;
create function pg_temp.draft(k text,e uuid,b integer,p jsonb) returns uuid language plpgsql as $$ declare v jsonb; begin v:=pg_temp.sync(pg_temp.op(k,e,b,p)); if v->>'status'<>'correction_draft' then raise exception 'fixture_not_draft: %',v; end if; return (v->>'draft_id')::uuid; end $$;
