-- These saved note-resolution drafts model the SQL contract; ordinary explicit
-- privacy resolution after finish remains an applied operation, not a draft.
create function pg_temp.saved_resolution(cid uuid,choice text) returns uuid language plpgsql security definer as $$
declare c public.workout_sync_conflicts; o jsonb; d uuid;
begin
 select * into c from public.workout_sync_conflicts where id=cid;
 o:=pg_temp.op('resolve_conflict',c.entity_id,c.expected_revision,jsonb_build_object('conflict_id',cid,'selected_version',choice,'expected_revision',c.expected_revision));
 insert into public.workout_correction_drafts(workspace_id,workout_instance_id,operation) values(c.workspace_id,c.workout_instance_id,o) returning id into d;
 insert into public.sync_operations(operation_id,workspace_id,user_id,device_id,kind,entity_id,base_revision,result,envelope)
 values((o->>'operation_id')::uuid,c.workspace_id,auth.uid(),(o->>'device_id')::uuid,'resolve_conflict',c.entity_id,c.expected_revision,jsonb_build_object('operation_id',o->>'operation_id','entity_id',c.entity_id,'status','correction_draft','revision',(select revision from public.workout_instances where id=c.workout_instance_id),'draft_id',d),o);
 return d;
end $$;
