create function pg_temp.corrupt(d uuid,o jsonb,matching_receipt boolean default true) returns void language plpgsql security definer as $$ begin
 update public.workout_correction_drafts set operation=o where id=d;
 if matching_receipt then update public.sync_operations set envelope=o where operation_id=(current_setting('test.bad_original')::jsonb->>'operation_id')::uuid; end if;
end $$;
